 * Name: test_API_policy_01_03.c
 * CaseID：
 * Description: 测试给media_policy_set_int设置合法的Numerical变量名、非法的变量值能否成功
 * 详细步骤如下：
 * 1：设置测试使用的变量为默认值
 * 2：调用media_policy_set_int测试函数，设置一个合法的Numerical变量名、非法的变量值
 * 3: 判断测试函数的返回值<0，判断该值是否没有被设置成功
 * 4：判断domain是否正确切换
 ****************************************************************************/
void test_API_policy_01_03(FAR void **state)
{
    int ret;
    ret = policy_set_criteria_defult(g_policy_info.numerical, 0);
    assert_int_equal(ret, 0);

    syslog(LOG_INFO, "policy test: testing media_policy_set_int\n");
    ret = media_policy_set_int(g_policy_info.numerical.name, 1024, 1);
    assert_true(ret < 0);

    media_policy_get_int(g_policy_info.numerical.name, &ret);
    assert_int_equal(ret, atoi(g_policy_info.numerical.default_value));

    syslog(LOG_INFO, "test_API_policy_01_03 pass\n");
}


