    assert_true(ret >= 0);

    media_policy_get_int(g_policy_info.inclusive.name, &ret);
    assert_int_equal(ret, g_policy_info.inclusive.value_for_int);

    syslog(LOG_INFO, "test_API_policy_01_04 pass\n");
