/****************************************************************************
 * Name: test_policy_interface_01_04.c
 * CaseID：
 * Description: 测试给media_uv_policy_set_int设置合法的TestInclu变量名、合法的变量值能否成功
 * 详细步骤如下：
 * 1：设置测试使用的变量为默认值
 * 2：调用media_uv_policy_set_int测试函数，设置一个合法的TestInclu变量名、合法的变量值，判断返回值是否>=0
 * 3: 判断测试函数的返回值>=0，判断该值是否被设置成功
 * 4：判断domain是否正确切换
 ****************************************************************************/
static void async_queue_cb_01_04(uv_async_queue_t* asyncq, void* data)
{
    uvpolicy_priv_s* priv = asyncq->data;
    int ret = 0;

    syslog(LOG_INFO, "policy test: testing media_uv_policy_set_int\n");
    ret = media_uv_policy_set_int(priv->loop, g_policy_info.inclusive.name,
        g_policy_info.inclusive.value_for_int, 1, policy_uv_common_cb, priv);
    assert_true(ret >= 0);
}

void test_API_uvpolicy_01_04(FAR void** state)
{
    int ret;
    uvpolicy_priv_s* priv = *state;
    priv->async_cb = async_queue_cb_01_04;

    ret = policy_set_criteria_defult(g_policy_info.inclusive, 0);
    assert_int_equal(ret, 0);

    pthread_mutex_lock(priv->mutex);
    uv_async_queue_send(&priv->async_queue, NULL);
    policy_uv_wait_callback(priv);
    pthread_mutex_unlock(priv->mutex);
    assert_true(priv->ret >= 0);

    media_policy_get_int(g_policy_info.inclusive.name, &ret);
    assert_int_equal(ret, g_policy_info.inclusive.value_for_int);
}

