 ****************************************************************************/
void test_API_policy_10_01(FAR void** state)
{
    int ret;

    ret = media_policy_set_stream_volume("abc", 1);
    assert_true(ret < 0);

    syslog(LOG_INFO, "test_API_policy_10_01 pass\n");
}

/****************************************************************************
 * Name: test_API_policy_10_03.c
 * CaseID：
 * Description: 测试给media_policy_set_stream_volume设置合法的变量名、非法的变量值能否被拒绝
 * 详细步骤如下：
 * 1：设置测试使用的变量为默认值
 * 2：调用media_policy_set_stream_volume测试函数，设置一个越界的变量值，判断返回值是否<0
 * 3：判断该值是否仍为默认值
 ****************************************************************************/
void test_API_policy_10_03(FAR void** state)
{
    int ret;
    char stream_name[48];

    sprintf(stream_name, "%sVolume", g_policy_criteria_info.stream_volume.name);
    media_policy_set_int(stream_name, atoi(g_policy_criteria_info.stream_volume.default_value), 1);
    media_policy_get_int(stream_name, &ret);
    assert_int_equal(ret, atoi(g_policy_criteria_info.stream_volume.default_value));

    /* 1024 越界，media_policy_set_stream_volume 应拒绝并返回 <0(-EINVAL) */
    ret = media_policy_set_stream_volume(g_policy_criteria_info.stream_volume.name, 1024);
    assert_true(ret < 0);

    media_policy_get_int(stream_name, &ret);
    assert_int_equal(ret, atoi(g_policy_criteria_info.stream_volume.default_value));

    syslog(LOG_INFO, "test_API_policy_10_03 pass\n");
}

/****************************************************************************
 * Name: test_API_policycase_10_04.c
 * CaseID：
 * Description: 测试给persist.media.MediaVolume变量短时间设置多次值，是否成功保存
 * 详细步骤如下：
 * 1：设置测试使用的变量为默认值
 * 2：调用run_count次media_policy_set_stream_volume测试函数，判断每次返回值是否>=0
 * 3：判断最后persist.media.MediaVolume的值是否符合预期
 ****************************************************************************/
void test_API_policy_10_04(FAR void** state)
{
    int ret;
    int run_count = 20;
    char stream_name[48];

    sprintf(stream_name, "%sVolume", g_policy_criteria_info.stream_volume.name);
    media_policy_set_int(stream_name, atoi(g_policy_criteria_info.stream_volume.default_value), 1);
    media_policy_get_int(stream_name, &ret);
    assert_int_equal(ret, atoi(g_policy_criteria_info.stream_volume.default_value));

    for (int i = 1; i <= run_count; i++) {
        ret = media_policy_set_stream_volume(g_policy_criteria_info.stream_volume.name, i % 3);
        assert_true(ret >= 0);
    }

    media_policy_get_int(stream_name, &ret);
    assert_int_equal(ret, run_count % 3);

    syslog(LOG_INFO, "test_API_policy_10_04 pass\n");
}

