173	static int media_policy_handler(MediadPlugin* ctx, struct media_server_conn* conn, const char* name, const char* cmd,
174	    const char* value, int apply, char* res, int res_len)
175	{
176	    MediaPolicyPriv* priv = ctx->priv;
177	    pfw_system_t* policy = priv->policy;
178	    int ret = -ENOSYS, tmp[2];
179	    void* handle;
180	    char* dump;
181	
182	    if (!cmd) {
183	        return -EINVAL;
184	    } else if (!strcmp(cmd, "ping")) {
185	        return 0;
186	    } else if (!strcmp(cmd, "subscribe")) {
187	        handle = pfw_subscribe(policy, name, media_policy_notify_cb, conn);
188	        if (!handle)
189	            return -EINVAL;
190	        media_server_set_data(conn, handle);
191	        return 0;
192	    } else if (!strcmp(cmd, "unsubscribe")) {
193	        handle = media_server_get_data(conn);
194	        pfw_unsubscribe(policy, handle);
195	        media_stub_notify_finalize((void**)&conn);
196	        return 0;
197	    } else if (!strcmp(cmd, "set_int")) {
198	        ret = pfw_setint(policy, name, atoi(value));
199	    } else if (!strcmp(cmd, "increase")) {
200	        ret = pfw_increase(policy, name);
201	    } else if (!strcmp(cmd, "decrease")) {
202	        ret = pfw_decrease(policy, name);
203	    } else if (!strcmp(cmd, "set_string")) {
204	        ret = pfw_setstring(policy, name, value);
205	    } else if (!strcmp(cmd, "include")) {
206	        ret = pfw_include(policy, name, value);
207	    } else if (!strcmp(cmd, "exclude")) {
208	        ret = pfw_exclude(policy, name, value);
209	    } else if (!strcmp(cmd, "contain")) {
210	        ret = pfw_contain(policy, name, value, &tmp[0]);
211	        if (ret >= 0) {
212	            MEDIA_DEBUG("%s %s %s %s ret:%d res:%d.",
213	                name, cmd, value ? value : "_", apply ? "apply" : "_", ret, tmp[0]);
214	            return snprintf(res, res_len, "%d", tmp[0]);
215	        }
216	    } else if (!strcmp(cmd, "get_int")) {
217	        ret = pfw_getint(policy, name, &tmp[0]);
218	        if (ret >= 0) {
219	            MEDIA_DEBUG("%s %s %s %s ret:%d res:%d.",
220	                name, cmd, value ? value : "_", apply ? "apply" : "_", ret, tmp[0]);
221	            return snprintf(res, res_len, "%d", tmp[0]);
222	        }
223	    } else if (!strcmp(cmd, "get_string")) {
224	        ret = pfw_getstring(policy, name, res, res_len);
225	        MEDIA_DEBUG("%s %s %s %s ret:%d res:%s.",
226	            name, cmd, value ? value : "_", apply ? "apply" : "_", ret, res);
227	        if (ret >= 0)
228	            return 0;
229	    } else if (!strcmp(cmd, "get_range")) {
230	        ret = pfw_getrange(policy, name, &tmp[0], &tmp[1]);
231	        if (ret >= 0) {
232	            MEDIA_DEBUG("%s %s %s %s ret:%d res:%d - %d.",
233	                name, cmd, value ? value : "_", apply ? "apply" : "_", ret, tmp[0], tmp[1]);
234	            return snprintf(res, res_len, "%d,%d", tmp[0], tmp[1]);
235	        }
236	    } else if (!strcmp(cmd, "dump")) {
237	        dump = pfw_dump(policy);
238	        MEDIA_INFO("\n%s", dump);
239	        free(dump);
240	        return 0;
241	    }
242

