int check_audio_position(void *handle)
{
    void *player = handle;
    int flag = 1;
    int times = 0;
    int stalled = 0;
    unsigned int position = 0, last_positon = 0;

    while (times < CHECK_POSTION_TIMES) {
        media_player_get_position(player, &position);
        if (position - last_positon < CHECK_POSTION_INTERVAL / 2 / 1000) {
            stalled++;
        }
        usleep(CHECK_POSTION_INTERVAL);
        times++;
        last_positon = position;
    }

    /* Tolerate a few stalled samples: on resume-from-pause the ALSA
     * buffer may briefly underrun (XRUN), so the first interval can lag
     * behind the threshold even though the player is still advancing.
     * The player is considered playing as long as most intervals advance.
     */
    flag = (stalled < CHECK_POSTION_TIMES / 2) ? 1 : 0;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += 3;

    /* The player posts intermediate events too (e.g. the STARTED emitted
     * during setup), so drain them against a fixed deadline until the
     * expected state arrives rather than asserting on a single post. */
    for (;;) {
        if (sem_timedwait(&priv->player_sem, &ts) == -1) {
            syslog(LOG_ERR, "[%s][%d] timeout waiting for player event %d (last=%d)\n",
                   __func__, __LINE__, expected_event, priv->player_last_event);
            assert_true(0);
            return;
        }

        if (priv->player_last_event == expected_event) {
            syslog(LOG_INFO, "[%s][%d] player event %d received\n",
                   __func__, __LINE__, expected_event);
            return;
        }
    }
}

